        name: {k: v for k, v in caches(obj).items() if k.startswith("_") and isinstance(v, (int, float, bool))}
        for name, obj in env.fixtures.items()
    }
    return {"env": simple, "fixtures": fixture}


def state_hash(env) -> str:
